<template><section class="report-shell"><div class="report-box"><header><h2>Relatório de Ocorrências</h2></header><div class="fields"><label>Período <span><input v-model="start" class="field" type="date"><b>até</b><input v-model="end" class="field" type="date"></span></label><label>Funcionário<select v-model="collector" class="field"><option value="">TODOS OS FUNCIONÁRIOS</option><option v-for="user in users" :key="user.id" :value="String(user.id)">{{ user.nome }}</option></select></label></div><footer><button class="primary-button" @click="print">🖨 Imprimir</button><button @click="reset">✖ Cancelar</button></footer><p class="hint">Mostra Fechado e Não pagou; o PDF permite abrir a localização no mapa.</p><p v-if="error" class="feedback feedback--error">{{ error }}</p></div></section></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {apiFetch,apiFetchBlob} from '@/services/http';const today=new Date().toISOString().slice(0,10),start=ref(today),end=ref(today),collector=ref(''),users=ref<Array<{id:number;nome:string}>>([]),error=ref('');onMounted(async()=>{try{users.value=await apiFetch('/financeiro/relatorios/recebimentos/cobradores')}catch{error.value='Não foi possível carregar os funcionários.'}});function reset(){start.value=today;end.value=today;collector.value='';error.value=''}async function print(){error.value='';const query=new URLSearchParams({data_inicial:start.value,data_final:end.value});if(collector.value)query.set('cobrador_id',collector.value);try{const blob=await apiFetchBlob(`/financeiro/relatorios/ocorrencias/imprimir?${query}`),url=URL.createObjectURL(blob);window.open(url,'_blank','noopener,noreferrer');window.setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(cause){error.value=cause instanceof Error?cause.message:'Não foi possível gerar o relatório.'}}</script>
<style scoped>.report-shell{padding:24px}.report-box{max-width:580px;margin:auto;border-top:2px solid #f59e0b;background:#fff;box-shadow:0 1px 8px #0002}.report-box header{padding:14px 18px;background:#f8fafc}.report-box h2{margin:0;font-size:17px;color:#374151}.fields{padding:26px 106px;display:grid;gap:13px}.fields>label{display:grid;grid-template-columns:78px 1fr;align-items:center;gap:8px;font-size:13px}.fields span{display:flex;gap:8px;align-items:center}.fields span input{min-width:0}footer{padding:14px;text-align:center;border-top:1px solid #e5e7eb;background:#f8fafc}footer button{margin:0 3px}.hint,.feedback{margin:0;padding:0 18px 14px;font-size:12px}@media(max-width:600px){.fields{padding:20px}.fields>label{grid-template-columns:1fr}}</style>
